+int ossl_sframe_set_lock_range(SFRAME_SET *fs, const UINT_RANGE *range)
+{
+    if (fs->range_locked
+        || range->start != fs->offset
+        || range->start >= range->end)
+        return 0;
+
+    fs->locked_range = *range;
+    fs->range_locked = 1;
+    return 1;
+}
+
+void ossl_sframe_set_unlock_range(SFRAME_SET *fs)
+{
+    assert(fs->range_locked);
+    fs->range_locked = 0;
+}
